CREATE   PROCEDURE [RX].[usp_Upsert_BookingData]
AS
BEGIN

	MERGE [RX].[BookingData] AS tgt
		USING [Work].[BookingData_RX] AS src
			ON tgt.[BookingId] = src.[BookingId]
	WHEN MATCHED THEN UPDATE SET
		tgt.[_RowIndex] = src.[_RowIndex],
		tgt.[_ParentKeyField] = src.[_ParentKeyField],
		tgt.[MeetingId] = src.[MeetingId],
		tgt.[ResourceName] = src.[ResourceName],
		tgt.[SpaceTypeName] = src.[SpaceTypeName],
		tgt.[BookingSystemName] = src.[BookingSystemName],
		tgt.[StartTime] = src.[StartTime],
		tgt.[EndTime] = src.[EndTime],
		tgt.[StartTimeOriginal] = src.[StartTimeOriginal],
		tgt.[EndTimeOriginal] = src.[EndTimeOriginal],
		tgt.[Subject] = src.[Subject],
		tgt.[IsPrivate] = src.[IsPrivate],
		tgt.[IsConfirmed] = src.[IsConfirmed],
		tgt.[IsEnded] = src.[IsEnded],
		tgt.[IsNoShow] = src.[IsNoShow],
		tgt.[IsInstant] = src.[IsInstant],
		tgt.[IsAM] = src.[IsAM],
		tgt.[IsPM] = src.[IsPM],
		tgt.[IsEOD] = src.[IsEOD],
		tgt.[IsWorkingDay] = src.[IsWorkingDay],
		tgt.[Organizer] = src.[Organizer],
		tgt.[OrganizerEmail] = src.[OrganizerEmail],
		tgt.[IsAllDay] = src.[IsAllDay],
		tgt.[BookingAttendees] = src.[BookingAttendees],
		tgt.[UnplannedBookingAttendees] = src.[UnplannedBookingAttendees],
		tgt.[UnplannedBookingAttendeesEmailList] = src.[UnplannedBookingAttendeesEmailList],
		tgt.[Country] = src.[Country],
		tgt.[City] = src.[City],
		tgt.[Site] = src.[Site],
		tgt.[Building] = src.[Building],
		tgt.[Floor] = src.[Floor],
		tgt.[CheckedInFrom] = src.[CheckedInFrom],
		tgt.[CheckedOutFrom] = src.[CheckedOutFrom],
		tgt.[ExtendedFrom] = src.[ExtendedFrom],
		tgt.[BookedFrom] = src.[BookedFrom],
		tgt.[ResourceId] = src.[ResourceId],
		tgt.[Occupancy] = src.[Occupancy],
		tgt.[BookingSystem] = src.[BookingSystem],
		tgt.[CheckedOutBy] = src.[CheckedOutBy],
		tgt.[ExtendedBy] = src.[ExtendedBy],
		tgt.[AutoCancellation] = src.[AutoCancellation],
		tgt.[OrganizersDepartments] = src.[OrganizersDepartments],
		tgt.[OrganizersTeams] = src.[OrganizersTeams],
		tgt.[CheckedOutByEmail] = src.[CheckedOutByEmail],
		tgt.[CheckedInByEmail] = src.[CheckedInByEmail],
		tgt.[ExtendedByEmail] = src.[ExtendedByEmail],
		tgt.[CheckedInBy] = src.[CheckedInBy],
		tgt.[Assigned] = src.[Assigned],
		tgt.[Location] = src.[Location],
		tgt.[Zone] = src.[Zone]
	WHEN NOT MATCHED BY TARGET THEN INSERT
	(
		[_RowIndex],
		[_ParentKeyField],
		[BookingId],
		[MeetingId],
		[ResourceName],
		[SpaceTypeName],
		[BookingSystemName],
		[StartTime],
		[EndTime],
		[StartTimeOriginal],
		[EndTimeOriginal],
		[Subject],
		[IsPrivate],
		[IsConfirmed],
		[IsEnded],
		[IsNoShow],
		[IsInstant],
		[IsAM],
		[IsPM],
		[IsEOD],
		[IsWorkingDay],
		[Organizer],
		[OrganizerEmail],
		[IsAllDay],
		[BookingAttendees],
		[UnplannedBookingAttendees],
		[UnplannedBookingAttendeesEmailList],
		[Country],
		[City],
		[Site],
		[Building],
		[Floor],
		[CheckedInFrom],
		[CheckedOutFrom],
		[ExtendedFrom],
		[BookedFrom],
		[ResourceId],
		[Occupancy],
		[BookingSystem],
		[CheckedOutBy],
		[ExtendedBy],
		[AutoCancellation],
		[OrganizersDepartments],
		[OrganizersTeams],
		[CheckedOutByEmail],
		[CheckedInByEmail],
		[ExtendedByEmail],
		[CheckedInBy],
		[Assigned],
		[Location],
		[Zone]
	)
	VALUES
	(
		src.[_RowIndex],
		src.[_ParentKeyField],
		src.[BookingId],
		src.[MeetingId],
		src.[ResourceName],
		src.[SpaceTypeName],
		src.[BookingSystemName],
		src.[StartTime],
		src.[EndTime],
		src.[StartTimeOriginal],
		src.[EndTimeOriginal],
		src.[Subject],
		src.[IsPrivate],
		src.[IsConfirmed],
		src.[IsEnded],
		src.[IsNoShow],
		src.[IsInstant],
		src.[IsAM],
		src.[IsPM],
		src.[IsEOD],
		src.[IsWorkingDay],
		src.[Organizer],
		src.[OrganizerEmail],
		src.[IsAllDay],
		src.[BookingAttendees],
		src.[UnplannedBookingAttendees],
		src.[UnplannedBookingAttendeesEmailList],
		src.[Country],
		src.[City],
		src.[Site],
		src.[Building],
		src.[Floor],
		src.[CheckedInFrom],
		src.[CheckedOutFrom],
		src.[ExtendedFrom],
		src.[BookedFrom],
		src.[ResourceId],
		src.[Occupancy],
		src.[BookingSystem],
		src.[CheckedOutBy],
		src.[ExtendedBy],
		src.[AutoCancellation],
		src.[OrganizersDepartments],
		src.[OrganizersTeams],
		src.[CheckedOutByEmail],
		src.[CheckedInByEmail],
		src.[ExtendedByEmail],
		src.[CheckedInBy],
		src.[Assigned],
		src.[Location],
		src.[Zone]
	);
END
